function validate([skills, k]) {
  if (skills.length < 2 || skills.length > 100000) return 'skills needs 2 to 100000 players.';
  if (k < 1 || k > 1000000000) return 'k is between 1 and 10^9.';
  if (skills.some(v => v < 1 || v > 1000000)) return 'Each skill is between 1 and 10^6.';
  if (new Set(skills).size !== skills.length) return 'All skills must be different.';
  return null;
}

