function findWinningPlayer(skills, k) {
  // Play the games literally with a real queue of player indices.
  const queue = skills.map((_, index) => index);
  const strongest = skills.indexOf(Math.max(...skills));
  let wins = 0;
  for (;;) {
    const first = queue.shift();
    const second = queue.shift();
    const winner = skills[first] > skills[second] ? first : second;
    const loser = winner === first ? second : first;
    wins = winner === first ? wins + 1 : 1;
    queue.unshift(winner);
    queue.push(loser);
    if (wins >= k) return winner;
    // The strongest player can never lose, so once it wins a game it will reach k wins too.
    if (winner === strongest) return winner;
  }
}

