function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 7);
  const top = size === 'large' || rand() < 0.3 ? 1000000 : 3 * n;
  const used = new Set();
  const skills = [];
  while (skills.length < n) {
    const value = 1 + Math.floor(rand() * top);
    if (!used.has(value)) {
      used.add(value);
      skills.push(value);
    }
  }
  const pick = rand();
  let k;
  if (pick < 0.15) k = 1000000000;
  else if (pick < 0.3) k = n - 1 + Math.floor(rand() * 3);
  else k = 1 + Math.floor(rand() * (size === 'large' ? 30 : n));
  return [skills, k];
}
